// Short sound effects, generated by scripts/make-sounds.mjs.

import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio'

import { getState } from './store'

const SOURCES = {
  tick: require('../assets/sounds/tick.wav'),
  goed: require('../assets/sounds/goed.wav'),
  airhorn: require('../assets/sounds/airhorn.wav'),
  combo: require('../assets/sounds/combo.wav'),
  boom: require('../assets/sounds/boom.wav'),
  zoem: require('../assets/sounds/zoem.wav'),
  buffering: require('../assets/sounds/buffering.wav'),
  sixseven: require('../assets/sounds/sixseven.wav'),
} as const

export type Sound = keyof typeof SOURCES

const players: Partial<Record<Sound, AudioPlayer>> = {}

export async function initSounds() {
  try {
    await setAudioModeAsync({ playsInSilentMode: true })
  } catch {
    // Web or an older OS: sounds still play when the phone is not on silent.
  }
  for (const name of Object.keys(SOURCES) as Sound[]) {
    if (!players[name]) players[name] = createAudioPlayer(SOURCES[name])
  }
}

export function play(name: Sound) {
  if (!getState().settings.sounds) return
  const p = players[name] ?? (players[name] = createAudioPlayer(SOURCES[name]))
  try {
    void p.seekTo(0)
    p.play()
  } catch {
    // A missed sound is not worth stopping the game for.
  }
}
